getRecentIncidentCount: function(userSysId) {
    var ga = new GlideAggregate('incident');
    ga.addQuery('assigned_to', userSysId);
    ga.addQuery('opened_at', '>=', gs.daysAgoStart(30));
    ga.addAggregate('COUNT');
    ga.query();
    if (ga.next()) {
        return parseInt(ga.getAggregate('COUNT'), 10);
    }
    return 0;
}

