getFilteredResults: function() {
    var tableName = this.getParameter('sysparm_table');
    var encodedQuery = this.getParameter('sysparm_query') || '';

    // Validate table exists
    if (!tableName || !new GlideRecord(tableName).isValid()) {
        return JSON.stringify({error: 'Invalid table', count: 0, sysIds: []});
    }

    // Get count via GlideAggregate
    var ga = new GlideAggregate(tableName);
    ga.addEncodedQuery(encodedQuery);
    ga.addAggregate('COUNT');
    ga.query();
    var count = 0;
    if (ga.next()) count = parseInt(ga.getAggregate('COUNT'), 10);

    // Get first 5 sys_ids
    var sysIds = [];
    var gr = new GlideRecord(tableName);
    gr.addEncodedQuery(encodedQuery);
    gr.setLimit(5);
    gr.query();
    while (gr.next()) sysIds.push(gr.getUniqueValue());

    return JSON.stringify({count: count, sysIds: sysIds});
}

