// Diagnostic Script — Run in Scripts Background
// Goal: Find all Assignment Rules on Incident,
// log their order and conditions, flag conflicts

scripting.modelAnswer:
var gr = new GlideRecord('sysrule_assignment');
gr.addQuery('table', 'incident');
gr.orderBy('order');
gr.query();

var ruleCount = 0;
var networkRules = [];

while (gr.next()) {
    ruleCount++;
    var info = 'Rule: ' + gr.name + ' | Order: ' + gr.order + 
               ' | Active: ' + gr.active + 
               ' | Group: ' + gr.assignment_group.getDisplayValue() + 
               ' | Condition: ' + gr.condition;
    gs.info(info);

    if (gr.condition.indexOf('Network') > -1 || 
        gr.script.indexOf('Network') > -1) {
        networkRules.push(gr.name + ' (order: ' + gr.order + ', active: ' + gr.active + ')');
    }
}

gs.info('=== SUMMARY ===');
gs.info('Total rules on Incident: ' + ruleCount);
gs.info('Network-related rules: ' + networkRules.join(', '));
if (networkRules.length > 1) {
    gs.info('⚠ CONFLICT: Multiple rules match Network category — check order precedence');
}

current.priority = 1;
current.work_notes = 'Incident escalated to Critical by ' + gs.getUserDisplayName() + ' on ' + new GlideDateTime().getDisplayValue();
current.update();

gs.eventQueue('incident.escalated', current, gs.getUserID(), gs.getUserDisplayName());

